mapper.select:
select r.id, r.case_id, r.title, r.env, r.is_delete, r.pass_count, r.total_count, r.success_count, r.fail_count, r.block_count, r.ignore_count, r.creator, r.modifier, r.description, r.choose_content, r.executors, r.gmt_created, r.gmt_modified, r.expect_start_time, r.expect_end_time, r.owner from exec_record r inner join test_case c on c.id = r.case_id where c.product_line_id = #{productLineId,jdbcType=BIGINT} and c.is_delete = 0 and r.is_delete = 0
and (r.title like concat('%', #{keyword}, '%') or cast(r.id as char) like concat('%', #{keyword}, '%') or cast(r.case_id as char) like concat('%', #{keyword}, '%'))
and find_in_set(#{owner}, replace(r.owner, ', ', ',')) > 0
and r.gmt_created >= #{beginTime}
and r.gmt_created <= #{endTime}
order by r.gmt_created desc, r.id desc

select case_id as caseId, count(*) as recordNum from exec_record where case_id in
#{caseId}
and is_delete=0 group by case_id
